<script setup lang="ts">
import PlaybackIcon from '../../../shared/ui/PlaybackIcon.vue'
import { t, formatDate } from '../../../shared/i18n'
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { listWorks, type LibraryItem } from '../api/works'
import {coverUrl} from '../api/covers'
import { audioUrl } from '../api/detail'
import { usePlayer } from '../../../shared/player/store'
const works=ref<LibraryItem[]>([]),error=ref(''),loading=ref(false),page=ref(0),filter=ref('all'),player=usePlayer()
const labels:Record<string,string>={LYRICS_DRAFT:'待完善歌词',READY_TO_GENERATE:'待生成歌曲',GENERATING:'生成中',CHECKING:'结果待核对',COMPLETED:'已完成',GENERATION_FAILED:'生成失败'}
const shown=computed(()=>works.value.filter(w=>filter.value==='all'||(filter.value==='completed'?w.status==='COMPLETED':['GENERATING','CHECKING'].includes(w.status))))
let alive=true,sequence=0
async function load(target=page.value,quiet=false){const turn=++sequence;if(!quiet)loading.value=true;error.value='';try{const found=await listWorks(target);if(alive&&turn===sequence){works.value=found;page.value=target}}catch(e){if(alive&&turn===sequence)error.value=e instanceof Error?e.message:'读取作品失败'}finally{if(turn===sequence)loading.value=false}}
function play(item:LibraryItem){if(!item.audioId)return;const track=(r:LibraryItem)=>({id:r.audioId!,title:r.songTitle||r.work.title||(r.work.recipient?t('写给{recipient}的歌',{recipient:r.work.recipient}):t('我的原创歌曲')),cover:coverUrl(r.work.id,r.coverId),audio:audioUrl(r.work.id,r.audioId!),provenance:r.audioOrigin!});player.setQueue(works.value.filter(w=>w.audioId).map(track));void player.toggle(track(item))}
const timer=window.setInterval(()=>{if(document.visibilityState==='visible'&&!loading.value&&works.value.some(w=>['GENERATING','CHECKING'].includes(w.status)))void load(page.value,true)},8000)
const visible=()=>{if(document.visibilityState==='visible')void load(page.value,true)}
const identityChanged=()=>{works.value=[];filter.value='all';void load(0)}
onMounted(()=>{window.addEventListener('qingfeng:identity-changed',identityChanged);void load();document.addEventListener('visibilitychange',visible)})
onBeforeUnmount(()=>{window.removeEventListener('qingfeng:identity-changed',identityChanged);alive=false;sequence++;window.clearInterval(timer);document.removeEventListener('visibilitychange',visible)})
</script>
<template><div class="creation-heading"><div><h1>{{ t('把每一份心意，留在歌里。') }}</h1><p class="backend-state">{{ t('故事、歌词和完成的歌曲，都在这里。') }}</p></div><RouterLink class="button" to="/create">{{ t('再写一首送给TA') }}</RouterLink></div><div class="library-toolbar"><div class="library-filters" role="group" :aria-label="t('筛选作品')"><button v-for="tab in [{id:'all',label:'全部作品'},{id:'completed',label:'已完成'},{id:'progress',label:'生成中'}]" :key="tab.id" :aria-pressed="filter===tab.id" :class="{active:filter===tab.id}" @click="filter=tab.id">{{ t(tab.label) }}</button></div><button class="text-button" :disabled="loading" @click="load()">{{ t('刷新作品') }}</button></div><p v-if="loading" class="notice" role="status">{{ t('正在读取作品…') }}</p><p v-if="error" class="notice error" role="alert">{{ t(error) }}</p><div v-if="shown.length" class="works-grid"><article v-for="item in shown" :key="item.work.id" class="module-card work-item library-song"><div class="library-art"><img :src="coverUrl(item.work.id,item.coverId)" :alt="t('歌曲封面')"><button v-if="item.audioId" class="library-play" :aria-label="player.current?.id===item.audioId&&player.playing?t('暂停'):t('试听歌曲')" @click="play(item)"><PlaybackIcon :playing="player.current?.id===item.audioId&&player.playing"/></button><span class="work-status" :class="item.status.toLowerCase()">{{ t(labels[item.status]||'待完善歌词') }}</span></div><div class="library-song-copy"><h2>{{ item.songTitle||item.work.title||(item.work.recipient?t('写给{recipient}的歌',{recipient:item.work.recipient}):t('我的原创歌曲')) }}</h2><p class="meta">{{ t('送给 {recipient}',{recipient:item.work.recipient}) }} · {{ t(item.work.occasion) }}</p><p v-if="item.status==='GENERATION_FAILED'" class="summary">{{ t('这次创作未完成，打开作品查看详情。故事和歌词都已保留。') }}</p><p v-else-if="item.status==='CHECKING'" class="summary">{{ t('创作结果仍在核对，请打开作品查看，避免重复提交。') }}</p><p v-else-if="!item.audioId" class="summary">{{ item.work.message||item.work.story||t('这个故事，等你慢慢写。') }}</p><p class="meta">{{ t('更新于') }} {{ formatDate(item.work.updatedAt) }}</p><RouterLink class="button secondary" :to="`/works/${item.work.id}`">{{ item.audioId?t('试听与送礼'):['GENERATING','CHECKING'].includes(item.status)?t('查看生成进度'):t('继续制作') }}</RouterLink></div></article></div><div v-else-if="!loading&&!error" class="module-card"><h2>{{ works.length?t('这个分类还没有作品'):t('第一首歌，从你的故事开始。') }}</h2><p>{{ t('填写故事后会自动保存，随时都可以继续。') }}</p><RouterLink v-if="!works.length" class="button" to="/create">{{ t('制作一首歌') }}</RouterLink></div><div class="actions"><button v-if="page>0" class="button secondary" :disabled="loading" @click="load(page-1)">{{ t('上一页') }}</button><button v-if="works.length===20" class="button secondary" :disabled="loading" @click="load(page+1)">{{ t('下一页') }}</button></div><RouterLink class="recovery-reminder" to="/account">{{ t('换设备前，记得保存作品找回码。') }}</RouterLink></template>
